// ❌ OLD: Initializing APM tools inside render paths or layouts
// creates race conditions, multiple redundant instances, and server/client confusion.
import { initMonitoring } from '@/lib/monitoring';

initMonitoring();

export default function Layout({ children }: { children: React.ReactNode }) {
  return <html><body>{children}</body></html>;
}

export async function register() {
  // ✅ NEW: Guaranteed to run only once at server boot time
  if (process.env.NEXT_RUNTIME === 'nodejs') {
    const { NodeSDK } = await import('@opentelemetry/sdk-node');
    const { OTLPTraceExporter } = await import('@opentelemetry/exporter-trace-otlp-http');

    const sdk = new NodeSDK({
      traceExporter: new OTLPTraceExporter(),
      serviceName: 'nextjs-web-app'
    });
    sdk.start();
  }
}
